\set ON_ERROR_STOP on
BEGIN;
DO $$
DECLARE p uuid:='11111111-1111-4111-8111-111111111111';b uuid:='22222222-2222-4222-8222-222222222222';u uuid:='33333333-3333-4333-8333-333333333333';d uuid:='44444444-4444-4444-8444-444444444444';pr uuid:='55555555-5555-4555-8555-555555555555';ba uuid:='66666666-6666-4666-8666-666666666666';s uuid:='77777777-7777-4777-8777-777777777777';si uuid:='88888888-8888-4888-8888-888888888888';r record; caught boolean;
BEGIN
  INSERT INTO auth.users(id,aud,role,email,created_at,updated_at)VALUES(u,'authenticated','authenticated','v2-harness@test.local',now(),now());
  INSERT INTO public.pharmacies(id,name,owner_id)VALUES(p,'Refund V2 Harness',u); INSERT INTO public.branches(id,pharmacy_id,name,is_main)VALUES(b,p,'Main',true); INSERT INTO public.pharmacy_members(user_id,pharmacy_id,role,default_branch_id,status)VALUES(u,p,'OWNER',b,'ACTIVE'); INSERT INTO public.devices(id,pharmacy_id,branch_id,registered_by,device_name,platform,public_key_pem,status)VALUES(d,p,b,u,'harness','WEB','test-key','ACTIVE'); INSERT INTO public.products(id,pharmacy_id,name,selling_price)VALUES(pr,p,'Product',250); INSERT INTO public.inventory_batches(id,pharmacy_id,product_id,branch_id,batch_number,quantity,cost_price,selling_price)VALUES(ba,p,pr,b,'Harness',10,1,250); INSERT INTO public.sales(id,pharmacy_id,branch_id,cashier_id,currency,subtotal,discount,tax,total,payment_method,amount_tendered,change_due,payment_status)VALUES(s,p,b,u,'NGN',1000,101,50,949,'CASH',949,0,'SETTLED'); INSERT INTO public.sale_items(id,sale_id,pharmacy_id,product_id,batch_id,quantity,unit_price,discount,tax,total)VALUES(si,s,p,pr,ba,4,250,0,0,1000);
  PERFORM set_config('request.jwt.claim.role','service_role',true);
  SELECT * INTO r FROM public.rpc_process_sale_return_v2(u,p,b,d,'99999999-9999-4999-8999-999999999999','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('a',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',2)),474,'CASH','first'); IF r.operation_status<>'COMMITTED' THEN RAISE EXCEPTION 'partial refund failed'; END IF;
  SELECT * INTO r FROM public.rpc_process_sale_return_v2(u,p,b,d,'99999999-9999-4999-8999-999999999999','cccccccc-cccc-4ccc-8ccc-cccccccccccc',repeat('a',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',2)),474,'CASH','first'); IF r.operation_status<>'ALREADY_COMMITTED' OR (SELECT count(*) FROM public.stock_ledger)<>1 THEN RAISE EXCEPTION 'idempotent replay failed'; END IF;
  caught:=false; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'99999999-9999-4999-8999-999999999999','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',repeat('f',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',2)),474,'CASH','conflict'); EXCEPTION WHEN unique_violation THEN caught:=true; END; IF NOT caught OR (SELECT count(*) FROM public.sale_returns)<>1 OR (SELECT count(*) FROM public.stock_ledger)<>1 THEN RAISE EXCEPTION 'payload conflict failed'; END IF;
  caught:=false; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'ffffffff-ffff-4fff-8fff-ffffffffffff','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('c',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),237,'CASH','nonce-reuse'); EXCEPTION WHEN unique_violation THEN caught:=true; END; IF NOT caught OR (SELECT count(*) FROM public.sale_returns)<>1 OR (SELECT count(*) FROM public.stock_ledger)<>1 THEN RAISE EXCEPTION 'nonce reuse failed'; END IF;
  SELECT * INTO r FROM public.rpc_process_sale_return_v2(u,p,b,d,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','dddddddd-dddd-4ddd-8ddd-dddddddddddd',repeat('b',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',2)),475,'CASH','second'); IF (SELECT sum(refund_amount_minor) FROM public.sale_returns)<>949 OR (SELECT quantity FROM public.inventory_batches WHERE id=ba)<>14 OR (SELECT count(*) FROM public.stock_ledger)<>2 THEN RAISE EXCEPTION 'rounding or inventory failed'; END IF;
  caught:=false; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','ffffffff-ffff-4fff-8fff-ffffffffffff',repeat('c',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),237,'CASH','over'); EXCEPTION WHEN check_violation THEN caught:=true; END; IF NOT caught THEN RAISE EXCEPTION 'over-refund not rejected'; END IF;
  caught:=false; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'12121212-1212-4121-8121-121212121212','13131313-1313-4131-8131-131313131313',repeat('d',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1),jsonb_build_object('sale_item_id',si,'quantity',1)),237,'CASH','duplicate'); EXCEPTION WHEN invalid_parameter_value THEN caught:=true; END; IF NOT caught THEN RAISE EXCEPTION 'duplicate item not rejected'; END IF;
  caught:=false; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'14141414-1414-4141-8141-141414141414','15151515-1515-4151-8151-151515151515',repeat('e',64),s,jsonb_build_array(jsonb_build_object('sale_item_id','99999999-9999-4999-8999-999999999999','quantity',1)),1,'CASH','missing'); EXCEPTION WHEN foreign_key_violation THEN caught:=true; END; IF NOT caught THEN RAISE EXCEPTION 'missing item not rejected'; END IF;
  PERFORM set_config('request.jwt.claim.role','authenticated',true); caught:=false; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'16161616-1616-4161-8161-161616161616','17171717-1717-4171-8171-171717171717',repeat('f',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),237,'CASH','role'); EXCEPTION WHEN insufficient_privilege THEN caught:=true; END; IF NOT caught THEN RAISE EXCEPTION 'non-service role not rejected'; END IF;
  PERFORM set_config('request.jwt.claim.role','service_role',true);
  RAISE NOTICE 'PASS: partial=474 replay=ALREADY_COMMITTED remainder=475 cumulative=949 stock=14 ledger=2';
END $$;

-- FIN-CUR-001, FIN-PAY-001, FIN-LEGACY-001, FIN-INPUT-001: real rejection paths.
-- Every failed RPC is caught in a subtransaction; it must leave no return, ledger,
-- journal, nonce, or stock mutation for this synthetic pharmacy.
DO $$
DECLARE
  p uuid:='61111111-1111-4111-8111-111111111111'; b uuid:='62222222-2222-4222-8222-222222222222';
  u uuid:='63333333-3333-4333-8333-333333333333'; d uuid:='64444444-4444-4444-8444-444444444444';
  pr uuid:='65555555-5555-4555-8555-555555555555'; ba uuid:='6a666666-6666-4666-8666-666666666666';
  s uuid:='67777777-7777-4777-8777-777777777777'; si uuid:='68888888-8888-4888-8888-888888888888';
  sc uuid:='6b777777-7777-4777-8777-777777777777'; sic uuid:='6c888888-8888-4888-8888-888888888888';
  caught boolean; v_sqlstate text;
BEGIN
  INSERT INTO auth.users(id,aud,role,email,created_at,updated_at) VALUES(u,'authenticated','authenticated','reject@test.local',now(),now());
  INSERT INTO public.pharmacies(id,name,owner_id) VALUES(p,'Refund V2 rejection tests',u);
  INSERT INTO public.branches(id,pharmacy_id,name,is_main) VALUES(b,p,'Main',true);
  INSERT INTO public.pharmacy_members(user_id,pharmacy_id,role,default_branch_id,status) VALUES(u,p,'OWNER',b,'ACTIVE');
  INSERT INTO public.devices(id,pharmacy_id,branch_id,registered_by,device_name,platform,public_key_pem,status) VALUES(d,p,b,u,'rejection-harness','WEB','reject-key','ACTIVE');
  INSERT INTO public.products(id,pharmacy_id,name,selling_price) VALUES(pr,p,'Reject product',100);
  INSERT INTO public.inventory_batches(id,pharmacy_id,product_id,branch_id,batch_number,quantity,cost_price,selling_price) VALUES(ba,p,pr,b,'REJECT',10,1,100);
  INSERT INTO public.sales(id,pharmacy_id,branch_id,cashier_id,currency,subtotal,discount,tax,total,payment_method,amount_tendered,change_due,payment_status) VALUES(s,p,b,u,'NGN',100,0,0,100,'CASH',100,0,'SETTLED');
  INSERT INTO public.sale_items(id,sale_id,pharmacy_id,product_id,batch_id,quantity,unit_price,discount,tax,total) VALUES(si,s,p,pr,ba,1,100,0,0,100);
  INSERT INTO public.sales(id,pharmacy_id,branch_id,cashier_id,currency,subtotal,discount,tax,total,payment_method,amount_tendered,change_due,payment_status) VALUES(sc,p,b,u,'EUR',100,0,0,100,'CASH',100,0,'SETTLED');
  INSERT INTO public.sale_items(id,sale_id,pharmacy_id,product_id,batch_id,quantity,unit_price,discount,tax,total) VALUES(sic,sc,p,pr,ba,1,100,0,0,100);
  PERFORM set_config('request.jwt.claim.role','service_role',true);

  caught:=false; v_sqlstate:=NULL;
  BEGIN
    PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'69999999-9999-4999-8999-999999999991','6bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1',repeat('1',64),sc,jsonb_build_array(jsonb_build_object('sale_item_id',sic,'quantity',1)),100,'CASH','currency');
  EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE; caught := v_sqlstate='22023'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=p)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=ba)<>10 THEN RAISE EXCEPTION 'FIN-CUR-001 expected SQLSTATE 22023 and no mutation, got %',v_sqlstate; END IF;

  caught:=false; v_sqlstate:=NULL;
  BEGIN
    PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','6ccccccc-cccc-4ccc-8ccc-ccccccccccc1',repeat('2',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),100,'CARD','payment');
  EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE; caught := v_sqlstate='23514'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=p)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=ba)<>10 THEN RAISE EXCEPTION 'FIN-PAY-001 expected SQLSTATE 23514 and no mutation, got %',v_sqlstate; END IF;

  -- Invalid quantities are rejected by the validated item parser before financial effects.
  caught:=false; v_sqlstate:=NULL;
  BEGIN
    PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'6ddddddd-dddd-4ddd-8ddd-ddddddddddd1','6eeeeeee-eeee-4eee-8eee-eeeeeeeeeee1',repeat('3',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',0)),1,'CASH','zero quantity');
  EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE; caught := v_sqlstate='22023'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=p)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=ba)<>10 THEN RAISE EXCEPTION 'FIN-INPUT-001 zero expected SQLSTATE 22023 and no mutation, got %',v_sqlstate; END IF;
  caught:=false; v_sqlstate:=NULL;
  BEGIN
    PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'6d111111-dddd-4ddd-8ddd-ddddddddddd1','6e111111-eeee-4eee-8eee-eeeeeeeeeee1',repeat('4',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',-1)),1,'CASH','negative quantity');
  EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE; caught := v_sqlstate='22023'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=p)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=ba)<>10 THEN RAISE EXCEPTION 'FIN-INPUT-001 negative expected SQLSTATE 22023 and no mutation, got %',v_sqlstate; END IF;
  caught:=false; v_sqlstate:=NULL;
  BEGIN
    PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'6d222222-dddd-4ddd-8ddd-ddddddddddd1','6e222222-eeee-4eee-8eee-eeeeeeeeeee1',repeat('5',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',2)),200,'CASH','excess quantity');
  EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE; caught := v_sqlstate='23514'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=p)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=ba)<>10 THEN RAISE EXCEPTION 'FIN-INPUT-001 excess expected SQLSTATE 23514 and no mutation, got %',v_sqlstate; END IF;
  caught:=false; v_sqlstate:=NULL;
  BEGIN
    PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'6d333333-dddd-4ddd-8ddd-ddddddddddd1','6e333333-eeee-4eee-8eee-eeeeeeeeeee1',repeat('6',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),99,'CASH','wrong expected amount');
  EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE; caught := v_sqlstate='23514'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=p)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=ba)<>10 THEN RAISE EXCEPTION 'FIN-INPUT-001 expected no mutation, got %',v_sqlstate; END IF;

  INSERT INTO public.sale_returns(id,pharmacy_id,branch_id,original_sale_id,refund_amount,refund_payment_method,reason,authorized_by,client_op_id,status,payload_hash,reconciliation_status) VALUES('6f000000-0000-4000-8000-000000000001',p,b,s,0,'CASH','legacy',u,'6f000000-0000-4000-8000-000000000002','COMPLETED',repeat('7',64),'LEGACY_UNVERIFIED');
  caught:=false; v_sqlstate:=NULL;
  BEGIN
    PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'6f000000-0000-4000-8000-000000000003','6f000000-0000-4000-8000-000000000004',repeat('8',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),100,'CASH','legacy protected');
  EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE; caught := v_sqlstate='23514'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=p)<>1 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=p)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=p)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=ba)<>10 THEN RAISE EXCEPTION 'FIN-LEGACY-001 expected SQLSTATE 23514 and no V2 mutation, got %',v_sqlstate; END IF;
  RAISE NOTICE 'FIN-CUR-001 PASS 22023; FIN-PAY-001 PASS 23514; FIN-INPUT-001 PASS [22023,22023,23514,23514]; FIN-LEGACY-001 PASS 23514; all mutation-free';
END $$;

-- FIN-ROUND-001: gross [300,200,100], discount 5 => [2,2,1], tax 2 => [1,1,0].
-- Entitlements [299,199,99]; first quantities [1,1,1] refund 247, remaining [2,1,1] refund 350.
DO $$
DECLARE p uuid:='51111111-1111-4111-8111-111111111111';b uuid:='52222222-2222-4222-8222-222222222222';u uuid:='53333333-3333-4333-8333-333333333333';d uuid:='54444444-4444-4444-8444-444444444444';a uuid:='55555555-5555-4555-8555-555555555551';c uuid:='55555555-5555-4555-8555-555555555552';e uuid:='55555555-5555-4555-8555-555555555553';ba uuid:='56666666-6666-4666-8666-666666666661';bc uuid:='56666666-6666-4666-8666-666666666662';be uuid:='56666666-6666-4666-8666-666666666663';s uuid:='57777777-7777-4777-8777-777777777777';i1 uuid:='58888888-8888-4888-8888-888888888881';i2 uuid:='58888888-8888-4888-8888-888888888882';i3 uuid:='58888888-8888-4888-8888-888888888883';r record; bad boolean;
BEGIN
INSERT INTO auth.users(id,aud,role,email,created_at,updated_at)VALUES(u,'authenticated','authenticated','round@test.local',now(),now());INSERT INTO public.pharmacies(id,name,owner_id)VALUES(p,'FIN-ROUND-001',u);INSERT INTO public.branches(id,pharmacy_id,name,is_main)VALUES(b,p,'B',true);INSERT INTO public.pharmacy_members(user_id,pharmacy_id,role,default_branch_id,status)VALUES(u,p,'OWNER',b,'ACTIVE');INSERT INTO public.devices(id,pharmacy_id,branch_id,registered_by,device_name,platform,public_key_pem,status)VALUES(d,p,b,u,'d','WEB','rkey','ACTIVE');INSERT INTO public.products(id,pharmacy_id,name,selling_price)VALUES(a,p,'A',100),(c,p,'C',100),(e,p,'E',50);INSERT INTO public.inventory_batches(id,pharmacy_id,product_id,branch_id,batch_number,quantity,cost_price,selling_price)VALUES(ba,p,a,b,'A',0,1,100),(bc,p,c,b,'C',0,1,100),(be,p,e,b,'E',0,1,50);INSERT INTO public.sales(id,pharmacy_id,branch_id,cashier_id,currency,subtotal,discount,tax,total,payment_method,amount_tendered,change_due,payment_status)VALUES(s,p,b,u,'NGN',600,5,2,597,'CASH',597,0,'SETTLED');INSERT INTO public.sale_items(id,sale_id,pharmacy_id,product_id,batch_id,quantity,unit_price,discount,tax,total)VALUES(i1,s,p,a,ba,3,100,0,0,300),(i2,s,p,c,bc,2,100,0,0,200),(i3,s,p,e,be,2,50,0,0,100);PERFORM set_config('request.jwt.claim.role','service_role',true);
SELECT * INTO r FROM public.rpc_process_sale_return_v2(u,p,b,d,'59999999-9999-4999-8999-999999999991','5bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1',repeat('3',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',i1,'quantity',1),jsonb_build_object('sale_item_id',i2,'quantity',1),jsonb_build_object('sale_item_id',i3,'quantity',1)),247,'CASH','round-1');IF (r.response_payload->>'refund_amount_minor')::bigint<>247 THEN RAISE EXCEPTION 'FIN-ROUND-001 first expected 247';END IF;
SELECT * INTO r FROM public.rpc_process_sale_return_v2(u,p,b,d,'5aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','5ccccccc-cccc-4ccc-8ccc-ccccccccccc1',repeat('4',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',i1,'quantity',2),jsonb_build_object('sale_item_id',i2,'quantity',1),jsonb_build_object('sale_item_id',i3,'quantity',1)),350,'CASH','round-2');IF (r.response_payload->>'refund_amount_minor')::bigint<>350 OR (SELECT sum(refund_amount_minor) FROM public.sale_returns WHERE pharmacy_id=p)<>597 OR (SELECT sum(quantity_delta) FROM public.stock_ledger WHERE pharmacy_id=p)<>7 THEN RAISE EXCEPTION 'FIN-ROUND-001 cumulative assertion';END IF;
IF (SELECT min(allocated_header_discount_minor) FROM public.sale_return_line_allocations WHERE sale_item_id=i1)=2 AND (SELECT min(allocated_header_discount_minor) FROM public.sale_return_line_allocations WHERE sale_item_id=i2)=2 AND (SELECT min(allocated_header_discount_minor) FROM public.sale_return_line_allocations WHERE sale_item_id=i3)=1 AND (SELECT min(allocated_header_tax_minor) FROM public.sale_return_line_allocations WHERE sale_item_id=i1)=1 AND (SELECT min(allocated_header_tax_minor) FROM public.sale_return_line_allocations WHERE sale_item_id=i2)=1 AND (SELECT min(allocated_header_tax_minor) FROM public.sale_return_line_allocations WHERE sale_item_id=i3)=0 THEN NULL; ELSE RAISE EXCEPTION 'FIN-ROUND-001 allocation'; END IF;
bad:=false;BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,'5ddddddd-dddd-4ddd-8ddd-ddddddddddd1','5eeeeeee-eeee-4eee-8eee-eeeeeeeeeee1',repeat('5',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',i1,'quantity',1)),99,'CASH','exhaust');EXCEPTION WHEN check_violation THEN bad:=true;END;IF NOT bad THEN RAISE EXCEPTION 'FIN-ROUND-001 exhaustion';END IF;RAISE NOTICE 'FIN-ROUND-001 PASS allocations disc=[2,2,1] tax=[1,1,0] refunds=[247,350] total=597 stock=7 ledger=6';END $$;

-- FIN-DISC-001: two equal gross lines, header discount=1; ascending item UUID gets the unit.
DO $$
DECLARE p uuid:='31111111-1111-4111-8111-111111111111';b uuid:='32222222-2222-4222-8222-222222222222';u uuid:='33333333-3333-4333-8333-333333333334';d uuid:='34444444-4444-4444-8444-444444444444';a uuid:='35555555-5555-4555-8555-555555555551';c uuid:='35555555-5555-4555-8555-555555555552';ba uuid:='36666666-6666-4666-8666-666666666661';bc uuid:='36666666-6666-4666-8666-666666666662';s uuid:='37777777-7777-4777-8777-777777777777';i1 uuid:='38888888-8888-4888-8888-888888888881';i2 uuid:='38888888-8888-4888-8888-888888888882';r record;
BEGIN
