DO $$
DECLARE p uuid:='21111111-1111-4111-8111-111111111111';b uuid:='22222222-2222-4222-8222-222222222223';u uuid:='23333333-3333-4333-8333-333333333333';d uuid:='24444444-4444-4444-8444-444444444444';pr uuid:='25555555-5555-4555-8555-555555555555';ba uuid:='26666666-6666-4666-8666-666666666666';s uuid:='27777777-7777-4777-8777-777777777777';si uuid:='28888888-8888-4888-8888-888888888888';r record;
