  PERFORM set_config('request.jwt.claim.role','service_role',true); SELECT * INTO r FROM public.rpc_process_sale_return_v2(u,p,b,d,'29999999-9999-4999-8999-999999999999','2bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('a',64),s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',4)),949,'CASH','full');
