  RAISE NOTICE 'FIN-FULL-001 PASS expected=949 actual=% stock=14 return=1 ledger=1',r.response_payload->>'refund_amount_minor';
END $$;

-- Authorization security gate. Every rejection is a real V2 RPC call and is
