DECLARE
  pa uuid:='71111111-1111-4111-8111-111111111111'; pb uuid:='72111111-1111-4111-8111-111111111111';
  ba1 uuid:='71222222-2222-4222-8222-222222222221'; ba2 uuid:='71222222-2222-4222-8222-222222222222'; bb1 uuid:='72222222-2222-4222-8222-222222222221';
