  INSERT INTO public.devices(id,pharmacy_id,branch_id,registered_by,device_name,platform,public_key_pem,status) VALUES
    (da1,pa,ba1,oa,'A1','WEB','auth-a1','ACTIVE'),(da2,pa,ba2,oa,'A2','WEB','auth-a2','ACTIVE'),(blocked,pa,ba1,oa,'blocked','WEB','auth-blocked','BLOCKED'),(db1,pb,bb1,ob,'B1','WEB','auth-b1','ACTIVE');
  INSERT INTO public.products(id,pharmacy_id,name,selling_price) VALUES(pra,pa,'Auth A product',100),(prb,pb,'Auth B product',100);
  INSERT INTO public.inventory_batches(id,pharmacy_id,product_id,branch_id,batch_number,quantity,cost_price,selling_price) VALUES(iba1,pa,pra,ba1,'AUTH-A1',10,1,100),(iba2,pa,pra,ba2,'AUTH-A2',10,1,100),(ibb1,pb,prb,bb1,'AUTH-B1',10,1,100);
  INSERT INTO public.sales(id,pharmacy_id,branch_id,cashier_id,currency,subtotal,discount,tax,total,payment_method,amount_tendered,change_due,payment_status) VALUES(sa1,pa,ba1,oa,'NGN',100,0,0,100,'CASH',100,0,'SETTLED'),(sa2,pa,ba2,oa,'NGN',100,0,0,100,'CASH',100,0,'SETTLED'),(sb1,pb,bb1,ob,'NGN',100,0,0,100,'CASH',100,0,'SETTLED');
  INSERT INTO public.sale_items(id,sale_id,pharmacy_id,product_id,batch_id,quantity,unit_price,discount,tax,total) VALUES(sia1,sa1,pa,pra,iba1,1,100,0,0,100),(sia2,sa2,pa,pra,iba2,1,100,0,0,100),(sib1,sb1,pb,prb,ibb1,1,100,0,0,100);
  PERFORM set_config('request.jwt.claim.role','service_role',true);

  -- AUTH-TENANT-001: valid A credentials cannot address B's sale through A's tenant scope.
  caught:=false; v_sqlstate:=NULL; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(oa,pa,ba1,da1,'71aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','71bbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('a',64),sb1,jsonb_build_array(jsonb_build_object('sale_item_id',sib1,'quantity',1)),100,'CASH','cross tenant'); EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate=RETURNED_SQLSTATE; caught:=v_sqlstate='02000'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=pa)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=iba1)<>10 OR (SELECT quantity FROM public.inventory_batches WHERE id=ibb1)<>10 THEN RAISE EXCEPTION 'AUTH-TENANT-001 %, mutation detected',v_sqlstate; END IF;

  -- AUTH-BRANCH-001: PHARMACIST is branch-bound; A1 membership cannot refund in A2.
  caught:=false; v_sqlstate:=NULL; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(pharmacist,pa,ba2,da2,'72aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','72bbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('b',64),sa2,jsonb_build_array(jsonb_build_object('sale_item_id',sia2,'quantity',1)),100,'CASH','cross branch'); EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate=RETURNED_SQLSTATE; caught:=v_sqlstate='42501'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=pa)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=iba2)<>10 THEN RAISE EXCEPTION 'AUTH-BRANCH-001 %, mutation detected',v_sqlstate; END IF;

  caught:=false; v_sqlstate:=NULL; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(inactive,pa,ba1,da1,'73aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','73bbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('c',64),sa1,jsonb_build_array(jsonb_build_object('sale_item_id',sia1,'quantity',1)),100,'CASH','inactive'); EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate=RETURNED_SQLSTATE; caught:=v_sqlstate='42501'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=pa)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=iba1)<>10 THEN RAISE EXCEPTION 'AUTH-MEMBER-001 %, mutation detected',v_sqlstate; END IF;
  caught:=false; v_sqlstate:=NULL; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(cashier,pa,ba1,da1,'74aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','74bbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('d',64),sa1,jsonb_build_array(jsonb_build_object('sale_item_id',sia1,'quantity',1)),100,'CASH','cashier'); EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate=RETURNED_SQLSTATE; caught:=v_sqlstate='42501'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=pa)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=iba1)<>10 THEN RAISE EXCEPTION 'AUTH-ROLE-001 %, mutation detected',v_sqlstate; END IF;
  caught:=false; v_sqlstate:=NULL; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(oa,pa,ba1,blocked,'75aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','75bbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('e',64),sa1,jsonb_build_array(jsonb_build_object('sale_item_id',sia1,'quantity',1)),100,'CASH','blocked device'); EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate=RETURNED_SQLSTATE; caught:=v_sqlstate='42501'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=pa)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=iba1)<>10 THEN RAISE EXCEPTION 'AUTH-DEVICE-001 %, mutation detected',v_sqlstate; END IF;
  caught:=false; v_sqlstate:=NULL; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(ob,pb,bb1,da1,'76aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','76bbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('f',64),sb1,jsonb_build_array(jsonb_build_object('sale_item_id',sib1,'quantity',1)),100,'CASH','foreign device'); EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate=RETURNED_SQLSTATE; caught:=v_sqlstate='42501'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=pb)<>0 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=pb)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=pb)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=pb)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=ibb1)<>10 THEN RAISE EXCEPTION 'AUTH-DEVICE-002 %, mutation detected',v_sqlstate; END IF;

  -- AUTH-JOURNAL-001: an existing V1 return op without a V2 journal cannot be replayed as V2.
