  caught:=false; v_sqlstate:=NULL; BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(oa,pa,ba2,da2,v1op,'77bbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('1',64),sa2,jsonb_build_array(jsonb_build_object('sale_item_id',sia2,'quantity',1)),100,'CASH','v2 over v1'); EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_sqlstate=RETURNED_SQLSTATE; caught:=v_sqlstate='23505'; END;
  IF NOT caught OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=pa)<>1 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=pa)<>0 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=pa)<>0 OR (SELECT quantity FROM public.inventory_batches WHERE id=iba2)<>10 THEN RAISE EXCEPTION 'AUTH-JOURNAL-001 %, mutation detected',v_sqlstate; END IF;

  -- AUTH-RPC-003: valid trusted-gateway context completes normally.
  SELECT * INTO r FROM public.rpc_process_sale_return_v2(oa,pa,ba1,da1,'78aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','78bbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('2',64),sa1,jsonb_build_array(jsonb_build_object('sale_item_id',sia1,'quantity',1)),100,'CASH','authorized');
  IF r.operation_status<>'COMMITTED' OR (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=pa)<>2 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=pa)<>1 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=pa)<>1 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=pa)<>1 OR (SELECT quantity FROM public.inventory_batches WHERE id=iba1)<>11 THEN RAISE EXCEPTION 'AUTH-RPC-003 failed'; END IF;

  -- AUTH-RPC-001/002: database grants deny direct anon/authenticated invocation.
  caught:=false; BEGIN EXECUTE 'SET LOCAL ROLE anon'; PERFORM * FROM public.rpc_process_sale_return_v2(oa,pa,ba1,da1,'79aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','79bbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('3',64),sa1,jsonb_build_array(jsonb_build_object('sale_item_id',sia1,'quantity',1)),100,'CASH','anon direct'); EXCEPTION WHEN insufficient_privilege THEN caught:=true; END; EXECUTE 'RESET ROLE'; IF NOT caught THEN RAISE EXCEPTION 'AUTH-RPC-001 direct anon execution allowed'; END IF;
  caught:=false; BEGIN EXECUTE 'SET LOCAL ROLE authenticated'; PERFORM * FROM public.rpc_process_sale_return_v2(oa,pa,ba1,da1,'7aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','7abbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('4',64),sa1,jsonb_build_array(jsonb_build_object('sale_item_id',sia1,'quantity',1)),100,'CASH','authenticated direct'); EXCEPTION WHEN insufficient_privilege THEN caught:=true; END; EXECUTE 'RESET ROLE'; IF NOT caught THEN RAISE EXCEPTION 'AUTH-RPC-002 direct authenticated execution allowed'; END IF;
  IF (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=pa)<>2 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=pa)<>1 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=pa)<>1 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=pa)<>1 OR (SELECT quantity FROM public.inventory_batches WHERE id=iba1)<>11 THEN RAISE EXCEPTION 'AUTH-RPC direct-role mutation detected'; END IF;
